Record Alumno
  Define nombre As String;
  Define nota As Real;
EndRecord
Algorithm Ficha
  Define ana As Alumno <- Alumno("Ana", 8.5);
  ana.nota <- ana.nota + 1;
  Write ana.nombre, ": ", ana.nota;
EndAlgorithm

Record Casilla
  Define fila, columna As Integer;
EndRecord
Algorithm Tablero
  Define a As Casilla <- Casilla(1, 2);
  Define b As Casilla <- a;
  b.fila <- 10;
  Write a.fila, " ", b.fila, " ", a = b;
EndAlgorithm

Record Casilla
  Define fila, columna As Integer;
EndRecord
Algorithm EscribirRegistro
  Write Casilla(1, 2);
EndAlgorithm

Record Casilla
  Define fila, columna As Integer;
EndRecord
Algorithm Faltan
  Define c As Casilla <- Casilla(1);
EndAlgorithm
